import { MongoMemoryReplSet } from 'mongodb-memory-server';
import mongodb from '../cloudflare/bananaboom-worker/node_modules/mongodb/lib/index.js';
const { MongoClient, ObjectId } = mongodb;
import {
  createDatabaseBackup, restoreBackupToEmptyDatabase
} from '../cloudflare/bananaboom-worker/src/databaseBackup.js';
import assert from 'node:assert/strict';

const replica = await MongoMemoryReplSet.create({
  replSet: { count: 1, storageEngine: 'wiredTiger' }
});
const client = new MongoClient(replica.getUri(), { serverSelectionTimeoutMS: 5000 });
// The URI is generated by the temporary local Mongo process. Never use MONGO_URI.
const objects = new Map();
const bucket = {
  put: async (key, value) => { objects.set(key,new Uint8Array(value)); },
  get: async (key) => {
    const buf=objects.get(key);
    return buf && {
      text:async()=>new TextDecoder().decode(buf),
      arrayBuffer:async()=>buf.buffer.slice(buf.byteOffset,buf.byteOffset+buf.byteLength)
    };
  },
  delete:async(key)=>{objects.delete(key);}
};

try {
  await client.connect();
  const source = client.db('orion_backup_test_source');
  await source.createCollection('users');
  await source.createCollection('posts');
  const owner = new ObjectId();
  await source.collection('users').insertOne({
    _id:owner, email:'sam@example.invalid',
    createdAt:new Date('2024-03-20T10:05:40Z'), flags:['owner','admin']
  });
  await source.collection('users').createIndex({email:1},{unique:true});
  await source.collection('posts').insertOne({
    _id:new ObjectId(), user:owner, tags:['中文','second-brain'], createdAt:new Date()
  });
  const snapshot=await createDatabaseBackup({
    client, db:source, bucket, maxRuntimeMs:25000
  });
  assert.equal(snapshot.collections,2);
  assert.equal(snapshot.documents,2);
  const dest=client.db('orion_restore_test_isolated_'+Date.now());
  const restored=await restoreBackupToEmptyDatabase({
    bucket, manifestKey:snapshot.manifestKey, targetDb:dest
  });
  assert.equal(restored.restored,2);
  const user=await dest.collection('users').findOne({_id:owner});
  assert.equal(user.email,'sam@example.invalid');
  assert.ok(user.createdAt instanceof Date);
  const indexes=await dest.collection('users').listIndexes().toArray();
  assert.ok(indexes.some((idx)=>idx.name==='email_1' && idx.unique===true));
  const post=await dest.collection('posts').findOne({user:owner});
  assert.deepEqual(post.tags,['中文','second-brain']);
  console.log('PASS: real local MongoDB replica-set snapshot and R2 checksum restore');
  console.log('Collection count:',snapshot.collections,'Document count:',snapshot.documents,'Part count:',restored.parts);
  await dest.dropDatabase();
} finally {
  await client.close();
  await replica.stop();
}
